using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Runtime.InteropServices;
namespace SargasPC {
 public sealed class AuditReport {public string Stage,Platform,State,CopyRestore,Isolation,NeutralScan,Error,Cleanup;public long At,ElapsedMs,ProcessCpuMs,ProcessPeakWorkingSet;public double? SystemCpuPercent;public bool NativeExecuted,ThreatEfficacyValidated=false,SoleAntivirusReady=false;}
 public static class AuditMetrics {public static double? Cpu(ulong idleBefore,ulong totalBefore,ulong idleAfter,ulong totalAfter){if(totalAfter<=totalBefore||idleAfter<idleBefore)return null;ulong total=totalAfter-totalBefore,idle=idleAfter-idleBefore;return idle>total?(double?)null:100.0*(total-idle)/total;}}
 public static class NativeAudit {
  [StructLayout(LayoutKind.Sequential)]struct Ft {public uint Low,High;public ulong Value{get{return ((ulong)High<<32)|Low;}}}
  [DllImport("kernel32.dll")]static extern bool GetSystemTimes(out Ft idle,out Ft kernel,out Ft user);
  static void DeleteOwnTree(string directory){FolderMonitor.NoLinks(directory);foreach(string entry in Directory.EnumerateFileSystemEntries(directory)){FolderMonitor.NoLinks(entry);if(Directory.Exists(entry))DeleteOwnTree(entry);else File.Delete(entry);}Directory.Delete(directory);}
  public static void ApplyResult(Core owner,AuditReport report){if(report==null||report.State!="CONTROL_COMPLETED_NOT_EFFICACY_PROOF"){owner.NotChecked++;owner.VisualEvent="UNCONFIRMED";}}
  public static string Run(Core owner){if(Environment.OSVersion.Platform!=PlatformID.Win32NT){ApplyResult(owner,null);return "NOT_RUN_WINDOWS_REQUIRED: Windows kontrolė nevykdyta. Tai nėra sėkmė.";}return RunWindows(owner);}
  [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]static string RunWindows(Core owner){owner.Check();string parent=Path.Combine(owner.Root,"acceptance");FolderMonitor.NoLinks(owner.Root);Directory.CreateDirectory(parent);FolderMonitor.NoLinks(parent);string root=Path.Combine(parent,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var report=new AuditReport{Platform=Environment.OSVersion.ToString(),At=DateTime.UtcNow.Ticks,State="INCOMPLETE",Stage="COPY_RESTORE",NativeExecuted=true,CopyRestore="NOT_RUN",Isolation="NOT_RUN",NeutralScan="NOT_RUN",Cleanup="NOT_RUN"};var clock=Stopwatch.StartNew();using(var proc=Process.GetCurrentProcess()){long cpu=(long)proc.TotalProcessorTime.TotalMilliseconds;Ft idle,kernel,user;bool initial=GetSystemTimes(out idle,out kernel,out user);ulong firstIdle=idle.Value,firstTotal=kernel.Value+user.Value;
   try{var c=new Core(Path.Combine(root,"profile"));c.ExternalCancellation=()=>owner.IsCancellationRequested;string path=Path.Combine(root,"neutral.txt");File.WriteAllText(path,new string('a',1048576),new UTF8Encoding(false));byte[] original=File.ReadAllBytes(path);var witness=c.Scan(path);c.Isolate(witness,false);if(!File.Exists(path))throw new IOException("Kopijos veiksmas pakeitė originalą.");var first=c.Vault().Single();string restored=Path.Combine(root,"restored.txt");c.Restore(first,restored);if(!File.ReadAllBytes(restored).SequenceEqual(original))throw new IOException("Atkurti baitai nesutampa.");bool blocked=false;try{c.Restore(first,restored);}catch(IOException){blocked=true;}if(!blocked)throw new IOException("Esamo failo perrašymas nebuvo atmestas.");report.CopyRestore="PASS_OWN_NEUTRAL_FILE";report.Stage="ISOLATION";c.Reset();witness=c.Scan(path);c.IsolateAndConfirm(witness);if(File.Exists(path)||c.VisualEvent!="REMOVAL_CONFIRMED"||!c.Vault().Any())throw new IOException("Nuosavo originalo izoliavimas nepatvirtintas.");report.Isolation="PASS_OWN_NEUTRAL_FILE";
    c.Reset();c.EngineBinaryDirectory=string.IsNullOrEmpty(owner.EngineBinaryDirectory)?Path.Combine(owner.EngineRoot,"clamav-1.4.6.win.x64"):owner.EngineBinaryDirectory;c.EngineDatabaseDirectory=owner.EngineDatabase;SharedEngine.UseIfAvailable(c);report.Stage="DATABASE_READINESS";EngineSafety.ValidateDatabaseFiles(c.EngineDatabase);report.Stage="NEUTRAL_SCAN";witness=c.Scan(restored);string scan=c.ScanLocalEngine(witness);report.NeutralScan=c.NotChecked>0?"INCOMPLETE":c.EngineFindings>0||c.HashFindings>0?"UNEXPECTED_DETECTION":"NO_SIGNATURES_ON_OWN_NEUTRAL_FILE";if(c.NotChecked>0||c.EngineFindings>0||c.HashFindings>0)throw new IOException("Neutralaus failo patikra nepatvirtinta: "+Data.CleanLog(scan));report.State="CONTROL_COMPLETED_NOT_EFFICACY_PROOF";
   }catch(Exception e){report.Error=Data.Clean(e.Message.Length>512?e.Message.Substring(0,512):e.Message)+"; "+Data.Diagnostic(e)+(report.Stage=="DATABASE_READINESS"?" — naudokite Atnaujinti → bendras bazes.":"");if(report.Stage=="DATABASE_READINESS")report.NeutralScan="BLOCKED_DATABASE_NOT_READY";report.State=e is OperationCanceledException?"CANCELLED":"INCOMPLETE";}
   finally{clock.Stop();report.ElapsedMs=clock.ElapsedMilliseconds;report.ProcessCpuMs=Math.Max(0,(long)proc.TotalProcessorTime.TotalMilliseconds-cpu);proc.Refresh();report.ProcessPeakWorkingSet=proc.PeakWorkingSet64;if(initial&&GetSystemTimes(out idle,out kernel,out user))report.SystemCpuPercent=AuditMetrics.Cpu(firstIdle,firstTotal,idle.Value,kernel.Value+user.Value);try{DeleteOwnTree(root);report.Cleanup="OWN_FIXTURES_REMOVED";}catch(Exception e){report.Cleanup="INCOMPLETE: "+Data.Diagnostic(e);report.State="INCOMPLETE";}}
  }
  ApplyResult(owner,report);string output=Path.Combine(owner.Root,"last-native-audit.json");Data.Atomic(output,Data.Json().Serialize(report));return (report.State=="CONTROL_COMPLETED_NOT_EFFICACY_PROOF"?"KONTROLĖ BAIGTA — tik nuosavi neutralūs failai":"KONTROLĖ NEUŽBAIGTA — skenavimo ar kito etapo sėkmė nepatvirtinta")+"\r\nEtapas: "+report.Stage+"\r\nPriežastis: "+report.Error+"\r\n"+Data.Json().Serialize(report)+"\r\n\r\nAtaskaita: "+output+"\r\nCPU yra visos sistemos vidurkis bandymo metu, įskaitant kitas programas. Proceso CPU ir atmintis neapima atskirų ClamAV procesų. Tai trumpa kontrolė, ne ilgalaikis baterijos / disko apkrovos ar tikrų grėsmių aptikimo bandymas. Windows saugos centro registracija ir apsauga prieš paleidimą neįgyvendintos.";
  }
 }
}
